mapper.select:
select * from b_haier_data
where create_date = #{day}
and status = 1
and push_status = 1

    and id>=#{minId}

order by id asc
limit 5000;

select min(id)
from b_haier_data
where local_id = #{localId}
  and status = 1;

insert.if:
