, source_id
, source_type
, type
, task_id
, cust_num
, batch_no
, push_status
, status
, create_date
, create_time
)
values

    (#{data.apiCode,jdbcType=VARCHAR}
    , #{data.sourceId,jdbcType=BIGINT}
    , #{data.sourceType,jdbcType=INTEGER}
    , #{data.type,jdbcType=VARCHAR}
    , #{data.taskId,jdbcType=VARCHAR}
    , #{data.custNum,jdbcType=VARCHAR}
    , #{data.batchNo,jdbcType=VARCHAR}
    , #{data.pushStatus,jdbcType=INTEGER}
    , #{data.status,jdbcType=INTEGER}
    , #{data.createDate,jdbcType=INTEGER}
    , #{data.createTime,jdbcType=TIMESTAMP}
    )
